use serde :: { Deserialize , Serialize } ; impl FileInfo { # [doc = " Creates a new FileInfo with the specified parameters."] pub fn new (start_line : u64 , end_line : u64 , total_lines : u64 , content_hash : String) -> Self { Self { start_line , end_line , total_lines , content_hash } } # [doc = " Returns true if this represents a partial file read"] pub fn is_partial (& self) -> bool { self . start_line > 0 || self . end_line < self . total_lines } }